// Secrets with one value for every Starlings workspace, kept once in the
// Cloudflare Secrets Store `starlings-shared` (MZ, 2026-10-04). A workspace
// binds each one as `SHARED_<NAME>`, but LiveKit's (WORKSPACE_SHARED_SECRET_NAMES); provisioning writes the bindings and the
// production check requires them, so nobody pastes a shared key per Worker.
// Per-workspace random secrets (SESSION_SIGNING_SECRET,
// GOOGLE_TOKEN_ENCRYPTION_KEY) stay Worker secrets, generated by the script.
//
// The values are set once, by hand:
//   wrangler secrets-store secret create <store id> --name <NAME> --scopes workers --remote

/** The store's id. Not a secret: it names the store, it does not open it. */
import { SHARED_SECRETS_STORE_ID } from './deployment-values.ts';

export { SHARED_SECRETS_STORE_ID };

export const SHARED_SECRET_NAMES = [
  'LIVEKIT_API_KEY',
  'LIVEKIT_API_SECRET',
  'GOOGLE_WEB_CLIENT_SECRET',
  'GOOGLE_CALENDAR_CLIENT_SECRET',
  'POSTMARK_API_KEY',
  // Signs a workspace's request to connect its support line to hq.
  'SUPPORT_LINK_KEY',
  // The hourly deploy check's read of envisioning/starlings (ops.ts). One
  // fine-grained token, Contents: read, for every Worker (2026-10-15).
  'GITHUB_DEPLOY_CHECK_TOKEN',
] as const;
export type SharedSecretName = (typeof SHARED_SECRET_NAMES)[number];

/**
 * Envisioning's LiveKit key pair. Envisioning keeps it as its own Worker
 * secrets; starlings-auth binds it for the LiveKit broker; no
 * other workspace binds it, and asks the broker over its LIVEKIT binding.
 */
export const LIVEKIT_SECRET_NAMES: readonly SharedSecretName[] = ['LIVEKIT_API_KEY', 'LIVEKIT_API_SECRET'];

/** The shared secrets a workspace binds: every one but LiveKit's. */
export const WORKSPACE_SHARED_SECRET_NAMES: readonly SharedSecretName[] = SHARED_SECRET_NAMES.filter((name) => !LIVEKIT_SECRET_NAMES.includes(name));

/**
 * Keys that one workspace keeps in the same store but does not share: the
 * binding has the secret's own name, and only the workspace that uses it
 * binds it. `APP_INTAKE_KEY` signs the app channel door (docs/SUPPORT.md).
 */
export const OWN_STORE_SECRET_NAMES = ['APP_INTAKE_KEY'] as const;
export type OwnStoreSecretName = (typeof OWN_STORE_SECRET_NAMES)[number];

/** The binding a Worker reads a shared secret through. Distinct from a plain secret of the same name. */
export function sharedSecretBinding(name: SharedSecretName): string {
  return `SHARED_${name}`;
}

/** The `secrets_store_secrets` entries a workspace's wrangler block carries. */
export function sharedSecretBindings(names: readonly SharedSecretName[] = SHARED_SECRET_NAMES) {
  return names.map((name) => ({ binding: sharedSecretBinding(name), store_id: SHARED_SECRETS_STORE_ID, secret_name: name }));
}
